def oligo_complements(oligo):
    complement = ""
    reverse = ""
    reverse_complement = ""
    oligo2 = ""
    for ch in oligo:
        upper = ch.upper()
        if upper == 'A':
            complement += 'T'
        elif upper == 'T' or upper == 'U':
            complement += 'A'
        elif upper == 'C':
            complement += 'G'
        elif upper == 'G':
            complement += 'C'
        else:
            # 未知字符（如 'N'）保留原字符，保证 complement 与 oligo 等长
            complement += ch
    for ch in oligo:
        if ch.upper() == 'U':
            oligo2 += 'T'
        else:
            oligo2 += ch

    i = len(oligo) - 1
    while i >= 0:
        reverse += oligo[i]
        reverse_complement += complement[i]
        i -= 1
    oligos = [oligo2, complement, reverse, reverse_complement]
    return oligos

